// ─── PARENT TABS ──────────────────────────────────────────────────────────────
function ParentTabs() {
  return (
    <Tab.Navigator screenOptions={{ headerShown: false, tabBarStyle }}>
      <Tab.Screen name="ParentHome" component={ParentHomeScreen}
        options={{ tabBarIcon: ({ focused }) => <TabIcon name="today" label="Today" focused={focused} />, tabBarLabel: () => null }} />
      <Tab.Screen name="WeeklyTab" component={WeeklySummaryTabScreen}
        options={{ tabBarIcon: ({ focused }) => <TabIcon name="bar-chart" label="Weekly" focused={focused} />, tabBarLabel: () => null }} />
      <Tab.Screen name="MessagesTab" component={ParentMessagesScreen}
        options={{ tabBarIcon: ({ focused }) => <TabIcon name="chatbubbles" label="Chat" focused={focused} />, tabBarLabel: () => null }} />
      <Tab.Screen name="ProfileTab" component={SettingsScreen}
        options={{ tabBarIcon: ({ focused }) => <TabIcon name="person" label="Me" focused={focused} />, tabBarLabel: () => null }} />
    </Tab.Navigator>
  );
}

// Wrapper for weekly summary as a tab — supports multi-child switching
function WeeklySummaryTabScreen() {
  return <WeeklySummaryAutoScreen />;
}

function WeeklySummaryAutoScreen() {
  const { profile } = useAuth();
  const [children, setChildren] = React.useState([]);
  const [selectedIdx, setSelectedIdx] = React.useState(0);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    async function load() {
      const { data } = await supabase
        .from('parent_children')
        .select('child:children(id, first_name)')
        .eq('parent_id', profile.id);
      const kids = (data || []).map(r => r.child).filter(Boolean);
      setChildren(kids);
      setLoading(false);
    }
    if (profile) load();
  }, [profile]);

  if (loading) return <LoadingScreen />;
  if (!children.length) return <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}><Text>No children linked</Text></View>;

  const selected = children[selectedIdx] || children[0];

  return (
    <View style={{ flex: 1 }}>
      {/* Child switcher tabs (show only if more than 1 child) */}
      {children.length > 1 && (
        <View style={childSwitcherStyles.row}>
          {children.map((child, i) => (
            <TouchableOpacity
              key={child.id}
              onPress={() => setSelectedIdx(i)}
              style={[childSwitcherStyles.tab, i === selectedIdx && childSwitcherStyles.tabActive]}
            >
              <Text style={[childSwitcherStyles.tabText, i === selectedIdx && childSwitcherStyles.tabTextActive]}>
                {child.first_name}
              </Text>
            </TouchableOpacity>
          ))}
        </View>
      )}
      <WeeklySummaryScreen route={{ params: { childId: selected.id, childName: selected.first_name } }} />
    </View>
  );
}

const childSwitcherStyles = StyleSheet.create({
  row: {
    flexDirection: 'row', backgroundColor: colors.surface,
    borderBottomWidth: 1, borderBottomColor: colors.border,
    paddingHorizontal: spacing.lg, paddingTop: spacing.md,
  },
  tab: {
    paddingHorizontal: spacing.lg, paddingVertical: spacing.sm,
    borderBottomWidth: 2, borderBottomColor: 'transparent',
    marginRight: spacing.sm,
  },
  tabActive: { borderBottomColor: colors.primary },
  tabText: { fontSize: 14, fontWeight: '500', color: colors.textMuted },
  tabTextActive: { color: colors.primary, fontWeight: '600' },
});

// ─── PROFILE ERROR FALLBACK ───────────────────────────────────────────────────
// Shown if a signed-in user has no profile row and self-heal failed.
function ProfileIssueScreen() {
  const { user, fetchProfile, signOut } = useAuth();
  return (
    <View style={styles.profileIssue}>
      <Text style={styles.profileIssueIcon}>⚠️</Text>
      <Text style={styles.profileIssueTitle}>We couldn't load your profile</Text>
      <Text style={styles.profileIssueText}>
        Your account exists but its profile is missing. Try again, or sign out
        and contact your daycare.
      </Text>
      <Button label="Try again" onPress={() => user && fetchProfile(user.id)} style={styles.profileIssueBtn} />
      <Button label="Sign out" onPress={signOut} variant="ghost" style={styles.profileIssueBtn} />
    </View>
  );
}

// ─── ROOT NAVIGATOR ───────────────────────────────────────────────────────────
function RootNavigator() {
  const { user, profile, loading, recovery } = useAuth();
  usePushNotifications(user?.id);
  if (loading) return <LoadingScreen />;

  const needsOnboarding = profile?.role === 'educator' && !profile?.classroom_id;

  return (
    <Stack.Navigator screenOptions={{ headerShown: false }}>
      {!user ? (
        <>
          <Stack.Screen name="Login"          component={LoginScreen} />
          <Stack.Screen name="Signup"         component={SignupScreen} />
          <Stack.Screen name="ForgotPassword" component={ForgotPasswordScreen} />
        </>
      ) : recovery ? (
        <Stack.Screen name="ResetPassword" component={ResetPasswordScreen} />
      ) : !profile ? (
        <Stack.Screen name="ProfileIssue" component={ProfileIssueScreen} />
      ) : needsOnboarding ? (
        <Stack.Screen name="Onboarding" component={OnboardingScreen} />
      ) : profile?.role === 'educator' ? (
        <>
          <Stack.Screen name="EducatorTabs"    component={EducatorTabs} />
          <Stack.Screen name="DailyLog"        component={DailyLogScreen}        options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="ChildProfile"    component={ChildProfileScreen}    options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="IncidentReport"  component={IncidentReportScreen}  options={{ animation: 'slide_from_bottom' }} />
          <Stack.Screen name="EditProfile"     component={EditProfileScreen}     options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="Messaging"       component={MessagingScreen}       options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="Privacy"         component={PrivacyScreen}         options={{ animation: 'slide_from_bottom' }} />
        </>
      ) : (
        <>
          <Stack.Screen name="ParentTabs"      component={ParentTabs} />
          <Stack.Screen name="WeeklySummary"   component={WeeklySummaryScreen}   options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="IncidentDetail"  component={IncidentDetailScreen}  options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="Messaging"       component={MessagingScreen}       options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="EditProfile"     component={EditProfileScreen}     options={{ animation: 'slide_from_right' }} />
          <Stack.Screen name="Privacy"         component={PrivacyScreen}         options={{ animation: 'slide_from_bottom' }} />
        </>
      )}
    </Stack.Navigator>
  );
}

export default function App() {
  // Complete Supabase auth deep links (magic-link invites, password recovery)
  React.useEffect(() => {
    Linking.getInitialURL().then(url => { if (url) handleAuthUrl(url); });
    const sub = Linking.addEventListener('url', ({ url }) => handleAuthUrl(url));
    return () => sub.remove();
  }, []);

  return (
    <SafeAreaProvider>
      <AuthProvider>
        <ClassroomProvider>
          <NavigationContainer ref={navigationRef}>
            <SafeAreaView style={styles.root} edges={['top', 'left', 'right']}>
              <OfflineBanner />
              <RootNavigator />
              <ToastHost />
            </SafeAreaView>
          </NavigationContainer>
        </ClassroomProvider>
      </AuthProvider>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: colors.bg },
  profileIssue: {
    flex: 1, justifyContent: 'center', alignItems: 'center',
    padding: spacing.xl, backgroundColor: colors.bg,
  },
  profileIssueIcon: { fontSize: 40, marginBottom: spacing.md },
  profileIssueTitle: {
    fontSize: 18, fontWeight: '700', color: colors.textPrimary,
    marginBottom: spacing.sm, textAlign: 'center',
  },
  profileIssueText: {
    fontSize: 14, color: colors.textSecondary, textAlign: 'center',
    lineHeight: 20, marginBottom: spacing.xl,
  },
  profileIssueBtn: { alignSelf: 'stretch', marginBottom: spacing.sm },
});

import React, { useState, useEffect } from 'react';
import { View, Image, Text, StyleSheet } from 'react-native';
import { supabase } from '../lib/supabase';
import { colors } from '../theme';

/**
 * Displays a child's profile photo or falls back to initials.
 * 
 * Props:
 *  - child: { first_name, last_name, photo_url }
 *  - size: number (default 48)
 *  - fontSize: number (default size * 0.35)
 */
export function ChildAvatar({ child, size = 48, fontSize }) {
  const [imageUrl, setImageUrl] = useState(null);
  const resolvedFontSize = fontSize || Math.round(size * 0.35);

  useEffect(() => {
    if (!child?.photo_url) {
      setImageUrl(null);
      return;
    }

    // Get a signed URL for the stored photo
    async function getUrl() {
      const { data } = await supabase.storage
        .from('child-avatars')
        .createSignedUrl(child.photo_url, 3600); // 1 hour
      if (data?.signedUrl) setImageUrl(data.signedUrl);
    }
    getUrl();
  }, [child?.photo_url]);

  const initials = `${child?.first_name?.[0] || '?'}${child?.last_name?.[0] || ''}`;

  const containerStyle = {
    width: size,
    height: size,
    borderRadius: size / 2,
  };

  if (imageUrl) {
    return (
      <Image
        source={{ uri: imageUrl }}
        style={[styles.image, containerStyle]}
      />
    );
  }

  return (
    <View style={[styles.fallback, containerStyle]}>
      <Text style={[styles.initials, { fontSize: resolvedFontSize }]}>
        {initials}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  image: {
    resizeMode: 'cover',
  },
  fallback: {
    backgroundColor: colors.primaryLight,
    alignItems: 'center',
    justifyContent: 'center',
  },
  initials: {
    fontWeight: '700',
    color: colors.primary,
  },
});

import React, { useState, useEffect } from 'react';
import { View, Image, Text, StyleSheet } from 'react-native';
import { supabase } from '../lib/supabase';
import { getCachedUrl, setCachedUrl } from '../lib/avatarCache';
import { colors } from '../theme';

/**
 * Displays a child's profile photo or falls back to initials.
 * Uses a module-level URL cache (55-min TTL) so roster focus
 * doesn't re-mint signed URLs for every avatar.
 *
 * Props:
 *  - child: { first_name, last_name, photo_url }
 *  - size: number (default 48)
 *  - fontSize: number (default size * 0.35)
 */
export function ChildAvatar({ child, size = 48, fontSize }) {
  const [imageUrl, setImageUrl] = useState(() => getCachedUrl(child?.photo_url));
  const resolvedFontSize = fontSize || Math.round(size * 0.35);

  useEffect(() => {
    if (!child?.photo_url) {
      setImageUrl(null);
      return;
    }

    const cached = getCachedUrl(child.photo_url);
    if (cached) {
      setImageUrl(cached);
      return;
    }

    // Get a signed URL for the stored photo
    async function getUrl() {
      const { data } = await supabase.storage
        .from('child-avatars')
        .createSignedUrl(child.photo_url, 3600); // 1 hour
      if (data?.signedUrl) {
        setCachedUrl(child.photo_url, data.signedUrl);
        setImageUrl(data.signedUrl);
      }
    }
    getUrl();
  }, [child?.photo_url]);

  const initials = `${child?.first_name?.[0] || '?'}${child?.last_name?.[0] || ''}`;

  const containerStyle = {
    width: size,
    height: size,
    borderRadius: size / 2,
  };

  if (imageUrl) {
    return (
      <Image
        source={{ uri: imageUrl }}
        style={[styles.image, containerStyle]}
      />
    );
  }

  return (
    <View style={[styles.fallback, containerStyle]}>
      <Text style={[styles.initials, { fontSize: resolvedFontSize }]}>
        {initials}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  image: {
    resizeMode: 'cover',
  },
  fallback: {
    backgroundColor: colors.primaryLight,
    alignItems: 'center',
    justifyContent: 'center',
  },
  initials: {
    fontWeight: '700',
    color: colors.primary,
  },
});

import React, { useState } from 'react';
import {
  View, Text, TouchableOpacity, StyleSheet, Modal, ScrollView
} from 'react-native';
import { colors, spacing, radius } from '../theme';

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function range(start, end) {
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

export function DatePickerField({ label, value, onChange }) {
  const [open, setOpen] = useState(false);

  const now = new Date();
  const parsed = value ? new Date(value + 'T00:00:00') : null;

  const [year,  setYear]  = useState(parsed?.getFullYear()  ?? 2022);
  const [month, setMonth] = useState(parsed?.getMonth()     ?? 0);
  const [day,   setDay]   = useState(parsed?.getDate()      ?? 1);

  const years = range(2015, now.getFullYear()).reverse();
  const days  = range(1, new Date(year, month + 1, 0).getDate());

  function confirm() {
    const mm = String(month + 1).padStart(2, '0');
    const dd = String(day).padStart(2, '0');
    onChange(`${year}-${mm}-${dd}`);
    setOpen(false);
  }

  const displayValue = value
    ? `${MONTHS[parseInt(value.split('-')[1]) - 1]} ${parseInt(value.split('-')[2])}, ${value.split('-')[0]}`
    : null;

  return (
    <View style={styles.wrap}>
      {label && <Text style={styles.label}>{label}</Text>}

      <TouchableOpacity onPress={() => setOpen(true)} style={styles.btn} activeOpacity={0.7}>
        <Text style={displayValue ? styles.btnText : styles.btnPlaceholder}>
          {displayValue || 'Select date of birth'}
        </Text>
        <Text style={styles.icon}></Text>
      </TouchableOpacity>

      <Modal transparent animationType="slide" visible={open}>
        <View style={styles.overlay}>
          <View style={styles.sheet}>
            <View style={styles.header}>
              <TouchableOpacity onPress={() => setOpen(false)}>
                <Text style={styles.cancel}>Cancel</Text>
              </TouchableOpacity>
              <Text style={styles.title}>Date of birth</Text>
              <TouchableOpacity onPress={confirm}>
                <Text style={styles.done}>Done</Text>
              </TouchableOpacity>
            </View>

            {/* Preview */}
            <Text style={styles.preview}>
              {MONTHS[month]} {day}, {year}
            </Text>

            <View style={styles.columns}>
              {/* Month */}
              <View style={styles.col}>
                <Text style={styles.colLabel}>Month</Text>
                <ScrollView style={styles.scroll} showsVerticalScrollIndicator={false}>
                  {MONTHS.map((m, i) => (
                    <TouchableOpacity
                      key={m}
                      onPress={() => setMonth(i)}
                      style={[styles.item, i === month && styles.itemSelected]}
                    >
                      <Text style={[styles.itemText, i === month && styles.itemTextSelected]}>{m}</Text>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              </View>

              {/* Day */}
              <View style={[styles.col, { width: 60 }]}>
                <Text style={styles.colLabel}>Day</Text>
                <ScrollView style={styles.scroll} showsVerticalScrollIndicator={false}>
                  {days.map(d => (
                    <TouchableOpacity
                      key={d}
                      onPress={() => setDay(d)}
                      style={[styles.item, d === day && styles.itemSelected]}
                    >
                      <Text style={[styles.itemText, d === day && styles.itemTextSelected]}>
                        {String(d).padStart(2, '0')}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              </View>

              {/* Year */}
              <View style={[styles.col, { width: 80 }]}>
                <Text style={styles.colLabel}>Year</Text>
                <ScrollView style={styles.scroll} showsVerticalScrollIndicator={false}>
                  {years.map(y => (
                    <TouchableOpacity
                      key={y}
                      onPress={() => setYear(y)}
                      style={[styles.item, y === year && styles.itemSelected]}
                    >
                      <Text style={[styles.itemText, y === year && styles.itemTextSelected]}>{y}</Text>
                    </TouchableOpacity>
                  ))}
                </ScrollView>
              </View>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { marginBottom: spacing.md },
  label: { fontSize: 13, fontWeight: '500', color: colors.textSecondary, marginBottom: spacing.xs },
  btn: {
    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
    borderWidth: 1.5, borderColor: colors.border, borderRadius: radius.md,
    paddingHorizontal: spacing.md, paddingVertical: spacing.md,
    backgroundColor: colors.surface,
  },
  btnText:        { fontSize: 15, color: colors.textPrimary },
  btnPlaceholder: { fontSize: 15, color: colors.textMuted },
  icon: { fontSize: 16 },
  overlay: { flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,0.45)' },
  sheet: {
    backgroundColor: colors.surface,
    borderTopLeftRadius: 24, borderTopRightRadius: 24,
    paddingBottom: 40,
  },
  header: {
    flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center',
    padding: spacing.lg, borderBottomWidth: 1, borderBottomColor: colors.border,
  },
  title:   { fontSize: 16, fontWeight: '600', color: colors.textPrimary },
  cancel:  { fontSize: 16, color: colors.textSecondary },
  done:    { fontSize: 16, color: colors.primary, fontWeight: '600' },
  preview: {
    textAlign: 'center', fontSize: 18, fontWeight: '600',
    color: colors.primary, paddingVertical: spacing.md,
  },
  columns: { flexDirection: 'row', justifyContent: 'center', gap: spacing.sm, paddingHorizontal: spacing.lg },
  col:     { width: 90, alignItems: 'center' },
  colLabel:{ fontSize: 11, fontWeight: '600', color: colors.textMuted, textTransform: 'uppercase', marginBottom: spacing.sm },
  scroll:  { height: 200 },
  item:    { paddingVertical: spacing.sm + 1, paddingHorizontal: spacing.sm, borderRadius: radius.md, alignItems: 'center', width: '100%' },
  itemSelected:     { backgroundColor: colors.primaryLight },
  itemText:         { fontSize: 16, color: colors.textSecondary },
  itemTextSelected: { color: colors.primary, fontWeight: '700' },
});

import React, { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Platform } from 'react-native';
import DateTimePicker from '@react-native-community/datetimepicker';
import { colors, spacing, radius } from '../theme';

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

export function DatePickerField({ label, value, onChange }) {
  const [show, setShow] = useState(false);

  const parsed = value ? new Date(value + 'T00:00:00') : null;

  const displayValue = value
    ? `${MONTHS[parseInt(value.split('-')[1]) - 1]} ${parseInt(value.split('-')[2])}, ${value.split('-')[0]}`
    : null;

  function handleChange(event, selectedDate) {
    if (Platform.OS === 'android') setShow(false);
    if (event.type === 'dismissed') { setShow(false); return; }
    if (selectedDate) {
      const y = selectedDate.getFullYear();
      const mm = String(selectedDate.getMonth() + 1).padStart(2, '0');
      const dd = String(selectedDate.getDate()).padStart(2, '0');
      onChange(`${y}-${mm}-${dd}`);
    }
    if (Platform.OS === 'ios') setShow(false);
  }

  return (
    <View style={styles.wrap}>
      {label && <Text style={styles.label}>{label}</Text>}

      <TouchableOpacity onPress={() => setShow(true)} style={styles.btn} activeOpacity={0.7}>
        <Text style={displayValue ? styles.btnText : styles.btnPlaceholder}>
          {displayValue || 'Select date of birth'}
        </Text>
        <Text style={styles.icon}></Text>
      </TouchableOpacity>

      {show && (
        <DateTimePicker
          value={parsed || new Date(2020, 0, 1)}
          mode="date"
          display={Platform.OS === 'ios' ? 'spinner' : 'default'}
          maximumDate={new Date()}
          minimumDate={new Date(2010, 0, 1)}
          onChange={handleChange}
        />
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { marginBottom: spacing.md },
  label: { fontSize: 13, fontWeight: '500', color: colors.textSecondary, marginBottom: spacing.xs },
  btn: {
    flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
    borderWidth: 1.5, borderColor: colors.border, borderRadius: radius.md,
    paddingHorizontal: spacing.md, paddingVertical: spacing.md,
    backgroundColor: colors.surface,
  },
  btnText:        { fontSize: 15, color: colors.textPrimary },
  btnPlaceholder: { fontSize: 15, color: colors.textMuted },
  icon: { fontSize: 16 },
});

import { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { mutate } from '../lib/offlineQueue';
import { newId } from '../lib/uuid';
import { showToast } from '../components/Toast';
import { format } from 'date-fns';

/**
 * Nap timer hook — manages live nap timers for a classroom.
 * - startNap: creates sleep_entry with end_time = null
 * - endNap: sets end_time
 * - 2.5h soft reminder toast
 * - Auto-close yesterday's open naps on mount
 */
export function useNapTimer(classroomId) {
  const [activeNaps, setActiveNaps] = useState({});
  const reminderInterval = useRef(null);
  const remindedSet = useRef(new Set());
  const today = format(new Date(), 'yyyy-MM-dd');

  const loadActiveNaps = useCallback(async () => {
    if (!classroomId) return;
    const { data: kids } = await supabase
      .from('children').select('id, first_name')
      .eq('classroom_id', classroomId).is('archived_at', null);
    if (!kids?.length) return;

    const childNames = {};
    kids.forEach(k => { childNames[k.id] = k.first_name; });

    const { data: logs } = await supabase
      .from('daily_logs').select('id, child_id')
      .in('child_id', kids.map(k => k.id)).eq('log_date', today);
    if (!logs?.length) { setActiveNaps({}); return; }

    const logToChild = {};
    logs.forEach(l => { logToChild[l.id] = l.child_id; });

    const { data: openSleeps } = await supabase
      .from('sleep_entries').select('id, daily_log_id, start_time')
      .in('daily_log_id', logs.map(l => l.id)).is('end_time', null);

    const naps = {};
    (openSleeps || []).forEach(s => {
      const childId = logToChild[s.daily_log_id];
      if (childId) {
        naps[childId] = {
          sleepEntryId: s.id, startTime: s.start_time,
          logId: s.daily_log_id, childName: childNames[childId] || 'Child',
        };
      }
    });
    setActiveNaps(naps);
  }, [classroomId, today]);

  useEffect(() => { loadActiveNaps(); }, [loadActiveNaps]);

  // Auto-close yesterday's open naps
  useEffect(() => {
    if (!classroomId) return;
    (async () => {
      const { data: kids } = await supabase
        .from('children').select('id')
        .eq('classroom_id', classroomId).is('archived_at', null);
      if (!kids?.length) return;
      const yesterday = format(new Date(Date.now() - 86400000), 'yyyy-MM-dd');
      const { data: oldLogs } = await supabase
        .from('daily_logs').select('id')
        .in('child_id', kids.map(k => k.id)).eq('log_date', yesterday);
      if (!oldLogs?.length) return;
      const { data: stale } = await supabase
        .from('sleep_entries').select('id')
        .in('daily_log_id', oldLogs.map(l => l.id)).is('end_time', null);
      if (stale?.length) {
        await supabase.from('sleep_entries')
          .update({ end_time: '23:59' }).in('id', stale.map(s => s.id));
      }
    })();
  }, [classroomId]);

  // 2.5h soft reminder — check every 60 seconds
  useEffect(() => {
    reminderInterval.current = setInterval(() => {
      const now = new Date();
      const nowMins = now.getHours() * 60 + now.getMinutes();
      Object.entries(activeNaps).forEach(([childId, nap]) => {
        if (!nap.startTime) return;
        const [h, m] = nap.startTime.split(':').map(Number);
        const elapsed = nowMins - (h * 60 + m);
        if (elapsed >= 150 && !remindedSet.current.has(nap.sleepEntryId)) {
          remindedSet.current.add(nap.sleepEntryId);
          const hrs = Math.floor(elapsed / 60);
          const mins = elapsed % 60;
          showToast(`⏰ ${nap.childName} has been napping ${hrs}h ${mins}m`, 'info');
        }
      });
    }, 60000);
    return () => { if (reminderInterval.current) clearInterval(reminderInterval.current); };
  }, [activeNaps]);

  async function startNap(childId, logId, childName = 'Child') {
    const now = format(new Date(), 'HH:mm');
    const id = newId();
    const row = { id, daily_log_id: logId, start_time: now, end_time: null };
    setActiveNaps(prev => ({
      ...prev,
      [childId]: { sleepEntryId: id, startTime: now, logId, childName },
    }));
    const { error } = await mutate({ type: 'insert', table: 'sleep_entries', data: row });
    if (error) {
      setActiveNaps(prev => { const next = { ...prev }; delete next[childId]; return next; });
      showToast(`Couldn't start nap: ${error.message}`, 'error');
    }
  }

  async function endNap(childId, endTimeOverride) {
    const nap = activeNaps[childId];
    if (!nap) return;
    const endTime = endTimeOverride || format(new Date(), 'HH:mm');
    setActiveNaps(prev => { const next = { ...prev }; delete next[childId]; return next; });
    remindedSet.current.delete(nap.sleepEntryId);
    const { error } = await mutate({
      type: 'update', table: 'sleep_entries',
      id: nap.sleepEntryId, data: { end_time: endTime },
    });
    if (error) {
      setActiveNaps(prev => ({ ...prev, [childId]: nap }));
      showToast(`Couldn't end nap: ${error.message}`, 'error');
    }
  }

  function isNapping(childId) { return !!activeNaps[childId]; }

  function getElapsed(childId) {
    const nap = activeNaps[childId];
    if (!nap?.startTime) return '';
    const [h, m] = nap.startTime.split(':').map(Number);
    const now = new Date();
    const elapsed = (now.getHours() * 60 + now.getMinutes()) - (h * 60 + m);
    if (elapsed <= 0) return '0m';
    if (elapsed < 60) return `${elapsed}m`;
    return `${Math.floor(elapsed / 60)}h ${elapsed % 60}m`;
  }

  function getOpenNaps() {
    return Object.entries(activeNaps).map(([childId, nap]) => ({ childId, ...nap }));
  }

  return { activeNaps, startNap, endNap, isNapping, getElapsed, getOpenNaps, refresh: loadActiveNaps };
}

/**
 * Avatar URL cache — avoids re-minting signed URLs on every ChildAvatar mount.
 * Stores { signedUrl, expiresAt } per storage path. TTL = 55 minutes
 * (signed URLs expire at 60 min, so we refresh 5 min early).
 */
const cache = new Map();
const TTL_MS = 55 * 60 * 1000; // 55 minutes

export function getCachedUrl(path) {
  const entry = cache.get(path);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
    cache.delete(path);
    return null;
  }
  return entry.signedUrl;
}

export function setCachedUrl(path, signedUrl) {
  cache.set(path, { signedUrl, expiresAt: Date.now() + TTL_MS });
}

export function clearAvatarCache() {
  cache.clear();
}

import React, { useState, useCallback } from 'react';
import {
  View, Text, ScrollView, TouchableOpacity,
